import { primaryKeyToFingerprint } from "./PrimaryKey.js";
import { displayFingerprint, fingerprintStartsWith, getFingerprintLength, normalizeFingerprintDisplay, fromFingerprintDisplay, sliceFingerprint } from "./Fingerprint.js";
import { nameRegex, nameStartRegex } from "./lib/characters.js";
import { nameToPrimaryChars } from "./lib/codec.js";
import isString from "./lib/utils/isString.js";
import { parseNameKey } from "./NameKey.js";
const MIN_NAME_LENGTH = 4;
const MIN_FINGERPRINTED_NAME_LENGTH = 10;
const MIN_FINGERPRINT_LENGTH = 3;
export const isName = (value) => {
    return isString(value) && value.length > 0 && nameRegex.test(value);
};
export const toPrimaryName = (name) => {
    if (isName(name) === false) {
        throw new Error("Invalid Name");
    }
    return nameToPrimaryChars(name);
};
export const parseFingerprintedName = (fingerprintedName) => {
    const match = fingerprintedName.match(nameStartRegex);
    if (match === null) {
        throw new Error("Invalid FingerprintedName");
    }
    const name = match[0];
    if (isName(name) === false) {
        throw new Error("Invalid FingerprintedName");
    }
    const fingerprintDisplay = fingerprintedName.slice(name.length);
    if (fingerprintDisplay.length === 0) {
        throw new Error("Invalid FingerprintedName");
    }
    const fingerprint = fromFingerprintDisplay(fingerprintDisplay);
    return [name, fingerprintDisplay, fingerprint];
};
export const isFingerprintedName = (value) => {
    if (isString(value) === false)
        return false;
    try {
        parseFingerprintedName(value);
        return true;
    }
    catch {
        return false;
    }
};
export const parseName = (name) => {
    if (isName(name)) {
        return [name, undefined, undefined];
    }
    else if (isFingerprintedName(name)) {
        return parseFingerprintedName(name);
    }
    throw new Error("Invalid Name or FingerprintedName");
};
export const isAcceptedName = (n, l = MIN_NAME_LENGTH) => {
    const name = isFingerprintedName(n) ? parseFingerprintedName(n)[0] : n;
    return name.length >= l;
};
export const isNameOrFingerprintedName = (value) => {
    return isName(value) || isFingerprintedName(value);
};
export const analyzeFingerprintedName = (fingerprintedName) => {
    const [name, fingerprintDisplay, fingerprint] = parseFingerprintedName(fingerprintedName);
    const nameLength = name.length;
    const fingerprintDisplayNormalized = normalizeFingerprintDisplay(fingerprintDisplay);
    const fingerprintLength = getFingerprintLength(fingerprint);
    const totalLength = nameLength + fingerprintLength;
    return { fingerprintedName, name, nameLength, fingerprintDisplay, fingerprintDisplayNormalized, fingerprint, fingerprintLength, totalLength };
};
export const nameBelongsToPrimaryKey = (name, primaryKey) => {
    return primaryKey.startsWith(nameToPrimaryChars(name));
};
export const fingerprintedNameBelongsToPrimaryKey = async (name, primaryKey) => {
    if (isFingerprintedName(name)) {
        const [n, , f] = parseFingerprintedName(name);
        const fingerprint = await primaryKeyToFingerprint(primaryKey);
        return primaryKey.startsWith(nameToPrimaryChars(n)) && fingerprintStartsWith(fingerprint, f);
    }
    else {
        return primaryKey.startsWith(nameToPrimaryChars(name));
    }
};
export const fingerprintedNameBelongsToNameKey = async (name, nameKey) => {
    const [primaryKey] = parseNameKey(nameKey);
    return await fingerprintedNameBelongsToPrimaryKey(name, primaryKey);
};
export const primaryKeyToFingerprintedName = async (primaryKey, name, fingerprintLength) => {
    if (nameBelongsToPrimaryKey(name, primaryKey) === false) {
        throw new Error("Name does not belong to PrimaryKey");
    }
    const l = MIN_FINGERPRINTED_NAME_LENGTH - name.length;
    const length = fingerprintLength ?? ((l >= MIN_FINGERPRINT_LENGTH) ? l : MIN_FINGERPRINT_LENGTH);
    const fingerprint = await primaryKeyToFingerprint(primaryKey);
    const fingerprintDisplay = displayFingerprint(sliceFingerprint(fingerprint, length));
    return [`${name}${fingerprintDisplay}`, name, fingerprintDisplay];
};
